CREATE SCHEMA IF NOT EXISTS "public";
CREATE TYPE "Role" AS ENUM ('USER', 'SUPPORT', 'NODE_MANAGER', 'ADMIN', 'SUPER_ADMIN');
CREATE TYPE "VpsStatus" AS ENUM ('PROVISIONING', 'RUNNING', 'STOPPED', 'SUSPENDED', 'ERROR', 'DELETING', 'DELETED');
CREATE TYPE "NodeStatus" AS ENUM ('ONLINE', 'OFFLINE', 'MAINTENANCE', 'ERROR');
CREATE TYPE "IpStatus" AS ENUM ('AVAILABLE', 'ASSIGNED', 'RESERVED', 'DISABLED');
CREATE TYPE "TaskStatus" AS ENUM ('QUEUED', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED');
CREATE TYPE "BackupStatus" AS ENUM ('QUEUED', 'RUNNING', 'COMPLETED', 'FAILED', 'DELETED');
CREATE TYPE "RdpProvider" AS ENUM ('DIRECT', 'TAILSCALE', 'PINGGY');
CREATE TYPE "TunnelStatus" AS ENUM ('DISABLED', 'INSTALLING', 'CONNECTED', 'RECONNECTING', 'OFFLINE', 'ERROR');
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"username" TEXT NOT NULL,"passwordHash" TEXT,"discordId" TEXT,"role" "Role" NOT NULL DEFAULT 'USER',"suspendedAt" TIMESTAMP(3),"lastLoginAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"planId" TEXT,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Node" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"address" TEXT NOT NULL,"status" "NodeStatus" NOT NULL DEFAULT 'OFFLINE',"agentVersion" TEXT,"lxdVersion" TEXT,"cpuCores" INTEGER,"ramMiB" INTEGER,"diskGiB" INTEGER,"tokenHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Node_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OsImage" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"distribution" TEXT NOT NULL,"release" TEXT NOT NULL,"architecture" TEXT NOT NULL DEFAULT 'amd64',"imageAlias" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OsImage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Plan" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"cpu" INTEGER NOT NULL,"ramMiB" INTEGER NOT NULL,"diskGiB" INTEGER NOT NULL,"vpsLimit" INTEGER NOT NULL,"ipv4" BOOLEAN NOT NULL DEFAULT false,"ipv6" BOOLEAN NOT NULL DEFAULT false,"rdp" BOOLEAN NOT NULL DEFAULT false,"sshx" BOOLEAN NOT NULL DEFAULT false,"tailscale" BOOLEAN NOT NULL DEFAULT false,"backups" BOOLEAN NOT NULL DEFAULT false,"snapshots" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "Plan_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Vps" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"hostname" TEXT NOT NULL,"lxdName" TEXT NOT NULL,"imageAlias" TEXT NOT NULL,"status" "VpsStatus" NOT NULL DEFAULT 'PROVISIONING',"cpu" INTEGER NOT NULL,"ramMiB" INTEGER NOT NULL,"diskGiB" INTEGER NOT NULL,"ipv6" TEXT,"privateIp" TEXT,"tailscaleIp" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3),"userId" TEXT NOT NULL,"nodeId" TEXT NOT NULL,"planId" TEXT,"osImageId" TEXT,CONSTRAINT "Vps_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IpAddress" ("id" TEXT NOT NULL,"address" TEXT NOT NULL,"gateway" TEXT,"cidr" INTEGER NOT NULL DEFAULT 32,"status" "IpStatus" NOT NULL DEFAULT 'AVAILABLE',"nodeId" TEXT NOT NULL,"vpsId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "IpAddress_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RdpAccess" ("id" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT false,"username" TEXT,"provider" "RdpProvider","status" "TunnelStatus" NOT NULL DEFAULT 'DISABLED',"host" TEXT,"port" INTEGER NOT NULL DEFAULT 3389,"passwordHash" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,"vpsId" TEXT NOT NULL,CONSTRAINT "RdpAccess_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Task" ("id" TEXT NOT NULL,"type" TEXT NOT NULL,"status" "TaskStatus" NOT NULL DEFAULT 'QUEUED',"progress" INTEGER NOT NULL DEFAULT 0,"payload" JSONB NOT NULL,"result" JSONB,"error" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"vpsId" TEXT,CONSTRAINT "Task_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Snapshot" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"sizeBytes" BIGINT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"vpsId" TEXT NOT NULL,CONSTRAINT "Snapshot_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Backup" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"status" "BackupStatus" NOT NULL DEFAULT 'QUEUED',"sizeBytes" BIGINT,"storageRef" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"vpsId" TEXT NOT NULL,CONSTRAINT "Backup_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Notification" ("id" TEXT NOT NULL,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"userId" TEXT NOT NULL,CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Setting" ("key" TEXT NOT NULL,"value" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,"updatedById" TEXT,CONSTRAINT "Setting_pkey" PRIMARY KEY ("key"));
CREATE TABLE "UiVersion" ("id" TEXT NOT NULL,"config" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"userId" TEXT NOT NULL,CONSTRAINT "UiVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"action" TEXT NOT NULL,"target" TEXT NOT NULL,"result" TEXT NOT NULL,"ip" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"actorId" TEXT,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "User_username_key" ON "User"("username");
CREATE UNIQUE INDEX "User_discordId_key" ON "User"("discordId");
CREATE UNIQUE INDEX "Node_name_key" ON "Node"("name");
CREATE UNIQUE INDEX "OsImage_name_key" ON "OsImage"("name");
CREATE UNIQUE INDEX "OsImage_imageAlias_key" ON "OsImage"("imageAlias");
CREATE UNIQUE INDEX "Plan_name_key" ON "Plan"("name");
CREATE UNIQUE INDEX "Vps_lxdName_key" ON "Vps"("lxdName");
CREATE INDEX "Vps_userId_idx" ON "Vps"("userId");
CREATE INDEX "Vps_nodeId_idx" ON "Vps"("nodeId");
CREATE UNIQUE INDEX "IpAddress_address_key" ON "IpAddress"("address");
CREATE UNIQUE INDEX "IpAddress_vpsId_key" ON "IpAddress"("vpsId");
CREATE UNIQUE INDEX "RdpAccess_vpsId_key" ON "RdpAccess"("vpsId");
CREATE UNIQUE INDEX "Snapshot_vpsId_name_key" ON "Snapshot"("vpsId", "name");
ALTER TABLE "User" ADD CONSTRAINT "User_planId_fkey" FOREIGN KEY ("planId") REFERENCES "Plan"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Vps" ADD CONSTRAINT "Vps_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Vps" ADD CONSTRAINT "Vps_nodeId_fkey" FOREIGN KEY ("nodeId") REFERENCES "Node"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Vps" ADD CONSTRAINT "Vps_planId_fkey" FOREIGN KEY ("planId") REFERENCES "Plan"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Vps" ADD CONSTRAINT "Vps_osImageId_fkey" FOREIGN KEY ("osImageId") REFERENCES "OsImage"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "IpAddress" ADD CONSTRAINT "IpAddress_nodeId_fkey" FOREIGN KEY ("nodeId") REFERENCES "Node"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "IpAddress" ADD CONSTRAINT "IpAddress_vpsId_fkey" FOREIGN KEY ("vpsId") REFERENCES "Vps"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "RdpAccess" ADD CONSTRAINT "RdpAccess_vpsId_fkey" FOREIGN KEY ("vpsId") REFERENCES "Vps"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Task" ADD CONSTRAINT "Task_vpsId_fkey" FOREIGN KEY ("vpsId") REFERENCES "Vps"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Snapshot" ADD CONSTRAINT "Snapshot_vpsId_fkey" FOREIGN KEY ("vpsId") REFERENCES "Vps"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Backup" ADD CONSTRAINT "Backup_vpsId_fkey" FOREIGN KEY ("vpsId") REFERENCES "Vps"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "UiVersion" ADD CONSTRAINT "UiVersion_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
